SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(d.pubmed_id, d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary md JOIN activities act ON md.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid LEFT JOIN docs d ON a.doc_id = d.doc_id LEFT JOIN compound_records cr ON act.record_id = cr.record_id JOIN compound_structures cs ON md.molregno = cs.molregno WHERE td.chembl_id = 'CHEMBL3717' AND act.standard_type = 'IC50' AND act.standard_units = 'nM' AND (d.pubmed_id IS NOT NULL OR d.doi IS NOT NULL) ORDER BY md.chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(d.pubmed_id, d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id, td.pref_name, td.organism
